import React from 'react';
import { Image, View, StyleSheet } from 'react-native';
// A small tileable monochrome noise texture (generated by generate-assets.js).
import GRAIN from '@/assets/grain.png';

interface GrainOverlayProps {
  opacity: number; // 0..1
}

/** Fine film grain, tiled across the parent. Sits above the photo, below UI. */
export function GrainOverlay({ opacity }: GrainOverlayProps) {
  if (opacity <= 0) return null;
  return (
    <View
      pointerEvents="none"
      style={[StyleSheet.absoluteFill, { opacity: Math.max(0, Math.min(1, opacity)) }]}
    >
      <Image source={GRAIN} resizeMode="repeat" style={StyleSheet.absoluteFill} />
    </View>
  );
}
